internal static class EditorTextures{
 private sealed record Request(string Input,string Output,string? Image=null,bool Resize=false);
 private static SKBitmap Decode(string file){
  var bytes=File.ReadAllBytes(file);if(!file.EndsWith(".tga",StringComparison.OrdinalIgnoreCase)){if(bytes.Length<24||!bytes.AsSpan(0,8).SequenceEqual(new byte[]{137,80,78,71,13,10,26,10}))throw new InvalidDataException("Expected PNG signature");var pw=System.Buffers.Binary.BinaryPrimitives.ReadUInt32BigEndian(bytes.AsSpan(16,4));var ph=System.Buffers.Binary.BinaryPrimitives.ReadUInt32BigEndian(bytes.AsSpan(20,4));if(pw<1||ph<1||pw>8192||ph>8192||(long)pw*ph>16777216)throw new InvalidDataException("Texture size limit");return SKBitmap.Decode(bytes)??throw new InvalidDataException("Invalid PNG");}
  if(bytes.Length<18||bytes[1]!=0||bytes[2] is not (2 or 10)||bytes[16] is not (24 or 32))throw new InvalidDataException("Expected true-color 24/32-bit TGA");var width=BitConverter.ToUInt16(bytes,12);var height=BitConverter.ToUInt16(bytes,14);if(width<1||height<1||width>8192||height>8192||(long)width*height>16777216)throw new InvalidDataException("Texture size limit");var bitmap=new SKBitmap(width,height,SKColorType.Rgba8888,SKAlphaType.Unpremul);var pixels=new SKColor[width*height];var at=18+bytes[0];var channels=bytes[16]/8;SKColor Read(){if(at+channels>bytes.Length)throw new InvalidDataException("Truncated TGA");var c=new SKColor(bytes[at+2],bytes[at+1],bytes[at],channels==4?bytes[at+3]:(byte)255);at+=channels;return c;}
  for(var i=0;i<pixels.Length;){var run=1;var repeated=false;if(bytes[2]==10){if(at>=bytes.Length)throw new InvalidDataException("Truncated TGA packet");var p=bytes[at++];run=(p&127)+1;repeated=(p&128)!=0;}if(i+run>pixels.Length)throw new InvalidDataException("Invalid TGA run");var c=repeated?Read():default;for(var j=0;j<run;j++)pixels[i++]=repeated?c:Read();}for(var y=0;y<height;y++)for(var x=0;x<width;x++)bitmap.SetPixel(x,y,pixels[((bytes[17]&32)!=0?y:height-y-1)*width+((bytes[17]&16)!=0?width-x-1:x)]);return bitmap;
 }
 internal static void Write(Texture texture,SKBitmap bitmap,string output){
  if(texture.Depth!=1||((int)texture.Flags&0x10)!=0||texture.GetSpriteSheetData() is not null)throw new InvalidDataException("Sheets, cube and volume textures are read-only");var levels=new List<SKColor[]>();var w=bitmap.Width;var h=bitmap.Height;var pixels=bitmap.Pixels;while(true){levels.Add(pixels);if(w==1&&h==1)break;var nw=Math.Max(1,w/2);var nh=Math.Max(1,h/2);var next=new SKColor[nw*nh];for(var y=0;y<nh;y++)for(var x=0;x<nw;x++){var p=new List<SKColor>();for(var dy=0;dy<2;dy++)for(var dx=0;dx<2;dx++)p.Add(pixels[Math.Min(h-1,y*2+dy)*w+Math.Min(w-1,x*2+dx)]);next[y*nw+x]=new SKColor((byte)p.Average(c=>c.Red),(byte)p.Average(c=>c.Green),(byte)p.Average(c=>c.Blue),(byte)p.Average(c=>c.Alpha));}pixels=next;w=nw;h=nh;}
  using var stream=File.Create(output);using var writer=new BinaryWriter(stream);writer.Write(68u);writer.Write((ushort)12);writer.Write((ushort)1);writer.Write(8u);writer.Write(1u);writer.Write(System.Text.Encoding.ASCII.GetBytes("DATA"));writer.Write(8u);writer.Write(40u);writer.Write((ushort)1);writer.Write((ushort)texture.Flags);for(var i=0;i<4;i++)writer.Write(0f);writer.Write((ushort)bitmap.Width);writer.Write((ushort)bitmap.Height);writer.Write((ushort)1);writer.Write((byte)4);writer.Write((byte)levels.Count);writer.Write(0u);writer.Write(0u);writer.Write(0u);foreach(var level in levels.AsEnumerable().Reverse())foreach(var p in level){writer.Write(p.Red);writer.Write(p.Green);writer.Write(p.Blue);writer.Write(p.Alpha);}
