 public static void Run(string manifest){var request=JsonSerializer.Deserialize<Request>(File.ReadAllText(manifest),new JsonSerializerOptions{PropertyNameCaseInsensitive=true})??throw new InvalidDataException("Empty texture request");using var r=new Resource{FileName=request.Input};r.Read(request.Input);if(r.DataBlock is not Texture texture)throw new InvalidDataException("Expected compiled texture");using var original=texture.GenerateBitmap();if(request.Image is null){using var image=SKImage.FromBitmap(original);using var data=image.Encode(SKEncodedImageFormat.Png,100);File.WriteAllBytes(request.Output,data.ToArray());Console.WriteLine(JsonSerializer.Serialize(new{width=original.Width,height=original.Height}));return;}using var bitmap=Decode(request.Image);if(!request.Resize&&(bitmap.Width!=original.Width||bitmap.Height!=original.Height))throw new InvalidDataException("Texture dimensions differ; explicitly allow resizing");Write(texture,bitmap,request.Output);using var check=new Resource{FileName=request.Output};check.Read(request.Output);if(check.DataBlock is not Texture result||result.Width!=bitmap.Width||result.Height!=bitmap.Height)throw new InvalidDataException("Texture verification failed");using var decoded=result.GenerateBitmap();if(!decoded.Pixels.SequenceEqual(bitmap.Pixels))throw new InvalidDataException("Texture pixel/alpha verification failed");Console.WriteLine(JsonSerializer.Serialize(new{width=bitmap.Width,height=bitmap.Height,mips=result.NumMipLevels}));}
}
